const body = $json.body ?? {};
const code = String(body.code ?? '').trim();
const providedLanguage = String(body.language ?? '').trim().toLowerCase();
const context = String(body.context ?? 'Não informado').trim();
const model = String(body.model ?? 'openai/gpt-4o-mini').trim();
const startedAt = Date.now();
function inferLanguage(input, source) {
  if (input) return input;
  if (/def\s+\w+\(|import\s+.+from\s+|self\.|pytest/.test(source)) return 'python';
  if (/<\?php|function\s+\w+\(|->|namespace\s+/.test(source)) return 'php';
  if (/interface\s+\w+|type\s+\w+\s*=|:\s*(string|number|boolean)|implements\s+/.test(source)) return 'typescript';
  if (/function\s+\w+\(|const\s+|let\s+|=>|module\.exports/.test(source)) return 'javascript';
  return 'generic';
}
const language = inferLanguage(providedLanguage, code);
const agents = {
  typescript: { name: 'typescript-review-agent', focus: 'TypeScript avançado, tipagem, async/await, arquitetura modular, segurança, testes Jest/Vitest e qualidade de API.' },
  javascript: { name: 'javascript-review-agent', focus: 'JavaScript moderno, Node.js/browser, closures, promises, validação, segurança, performance e testes.' },
  python: { name: 'python-review-agent', focus: 'Python, typing, PEP8, erros comuns, segurança, performance, pytest e organização de módulos.' },
  php: { name: 'php-review-agent', focus: 'PHP moderno, PSR, Composer, segurança web, validação, performance e testes PHPUnit.' },
  generic: { name: 'generic-review-agent', focus: 'Revisão geral de código, bugs, segurança, qualidade, performance, testes e manutenibilidade.' }
};
const agent = agents[language] ?? agents.generic;
const validationErrors = [];
if (!code) validationErrors.push({ field: 'code', message: 'O campo code é obrigatório.' });
if (code.length > 60000) validationErrors.push({ field: 'code', message: 'O código enviado é grande demais para este endpoint.' });
const runId = `run_${Date.now()}_${Math.random().toString(16).slice(2)}`;
const schema = { score: 0, severity: 'low|medium|high|critical', summary: 'string', assessment: 'approve|needs_work|requires_changes', positive_observations: ['string'], findings: [{ severity: 'critical|warning|suggestion', category: 'functionality|security|quality|testing|performance|maintainability', message: 'string', recommendation: 'string' }], recommendations: ['string'], test_suggestions: ['string'], security_notes: ['string'], complexity_assessment: 'string' };
const systemPrompt = `Você é o ${agent.name}. Foco: ${agent.focus} Responda APENAS JSON válido, sem markdown fora do JSON, no schema: ${JSON.stringify(schema)}. Seja criterioso e profissional. Use severidades: critical para falhas graves, warning para problemas relevantes, suggestion para melhorias. Atribua score de 0 a 100.`;
const userPrompt = `Contexto do projeto/case: ${context}\nLinguagem detectada: ${language}\n\nCódigo para revisão:\n\`\`\`\n${code}\n\`\`\``;
return [{ json: { run_id: runId, started_at_ms: startedAt, input: body, code, language, context, model, specialist_agent: agent.name, validation_errors: validationErrors, system_prompt: systemPrompt, user_prompt: userPrompt, langsmith: { tracing: $env.LANGSMITH_TRACING === 'true', project: $env.LANGSMITH_PROJECT || 'case-n8n', endpoint: $env.LANGSMITH_ENDPOINT || 'https://api.smith.langchain.com' } } }];

const request = $('Validate Input + Route Specialist').item.json;
const provider = $json;
const content = provider.choices?.[0]?.message?.content ?? '{}';
let structured;
try {
  structured = JSON.parse(content);
} catch (error) {
  structured = { score: 0, severity: 'high', assessment: 'requires_changes', summary: 'A IA retornou conteúdo fora do JSON estruturado esperado.', positive_observations: [], findings: [{ severity: 'warning', category: 'quality', message: content, recommendation: 'Reexecutar a análise ou ajustar o prompt/schema.' }], recommendations: ['Validar o formato de saída do agente.'], test_suggestions: [], security_notes: [], complexity_assessment: 'indisponível' };
}
const usage = provider.usage ?? {};
const durationMs = Math.max(0, Date.now() - request.started_at_ms);
const promptTokens = usage.prompt_tokens ?? 0;
const completionTokens = usage.completion_tokens ?? 0;
const totalTokens = usage.total_tokens ?? (promptTokens + completionTokens);
let estimatedCostUsd = null;
if ((provider.model ?? request.model).includes('gpt-4o-mini')) {
  estimatedCostUsd = Number((((promptTokens / 1000000) * 0.15) + ((completionTokens / 1000000) * 0.60)).toFixed(8));
}
const response = { data: { flow_type: 'review', status: 'completed', language: request.language, specialist: request.specialist_agent, model_used: provider.model ?? request.model, score: structured.score ?? null, severity: structured.severity ?? 'unknown', assessment: structured.assessment ?? 'needs_work', summary: structured.summary ?? '', positive_observations: structured.positive_observations ?? [], findings: structured.findings ?? [], recommendations: structured.recommendations ?? [], test_suggestions: structured.test_suggestions ?? [], security_notes: structured.security_notes ?? [], complexity_assessment: structured.complexity_assessment ?? null }, metrics: { duration_ms: durationMs, prompt_tokens: promptTokens, completion_tokens: completionTokens, total_tokens: totalTokens, estimated_cost_usd: estimatedCostUsd, provider_response_id: provider.id ?? null, finish_reason: provider.choices?.[0]?.finish_reason ?? null }, observability: { langsmith_tracing_enabled: request.langsmith.tracing, langsmith_project: request.langsmith.project, langsmith_endpoint: request.langsmith.endpoint }, meta: { run_id: request.run_id, timestamp: new Date().toISOString() } };
function sql(value) { return String(value).replace(/'/g, '\x27\x27'); }
const inputPayload = JSON.stringify({ language: request.language, context: request.context, code: request.code });
const outputPayload = JSON.stringify(response);
const dbQuery = `INSERT INTO agent_runs (id, flow_type, status, input_payload, output_payload, duration_ms, model_used) VALUES (gen_random_uuid(), 'review', 'completed', '${sql(inputPayload)}'::jsonb, '${sql(outputPayload)}'::jsonb, ${durationMs}, '${sql(response.data.model_used)}');`;
return [{ json: { response, db_query: dbQuery } }];
